mapper.select:

where 1=1
and s.supplier_name like concat('%', #{supplierName}, '%')
and s.supplier_code = #{supplierCode}
and s.contact_phone like concat('%', #{contactPhone}, '%')
and s.cooperation_status = #{cooperationStatus}
and s.shop_dept_id = #{shopDeptId}
and s.status = #{status}
and s.shop_dept_id in #{deptId}
${params.dataScope}
order by s.create_time desc


where s.supplier_name = #{supplierName}
  and s.status = '0'
  and s.cooperation_status = '0'
and s.shop_dept_id = #{shopDeptId}
order by s.supplier_id desc
limit 1

select count(1)
from inv_supplier
where shop_dept_id = #{shopDeptId}
  and supplier_name = #{supplierName}
and supplier_id != #{excludeSupplierId}

select count(1)
from inv_supplier
where shop_dept_id = #{shopDeptId}
  and supplier_code = #{supplierCode}
and supplier_id != #{excludeSupplierId}

